import{_ as a,C as l,o as n,c as s,j as t,a as o,E as i,a2 as d}from"./chunks/framework.DBmpDOAE.js";const w=JSON.parse('{"title":"5. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),h={name:"gdd/changelog.md"},g={id:"latest-main",tabindex:"-1"};function p(c,e,m,u,v,b){const r=l("Badge");return n(),s("div",null,[e[3]||(e[3]=t("h1",{id:"_5-changelog",tabindex:"-1"},[o("5. Changelog "),t("a",{class:"header-anchor",href:"#_5-changelog","aria-label":'Permalink to "5. Changelog"'},"​")],-1)),e[4]||(e[4]=t("p",null,[o("Every published version stays playable at its own URL. The "),t("a",{href:"https://taigd98.github.io/dot-line/",target:"_blank",rel:"noreferrer"},"landing page"),o(" lists them all.")],-1)),t("h2",g,[e[0]||(e[0]=o("latest (main) ",-1)),i(r,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),e[5]||(e[5]=d('<ul><li><strong>New level order:</strong> chapter 5&#39;s levels 25–28 now come right after the two tutorials (LEVEL 3–6); the pinch-to-zoom tutorial moved with them to LEVEL 3. Pumpkin (now LEVEL 7) was reworked by hand (17 lines).</li></ul><p><a href="https://taigd98.github.io/dot-line/demo/" target="_blank" rel="noreferrer">Play latest</a></p><h2 id="v0-3-0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0-3-0" aria-label="Permalink to &quot;v0.3.0&quot;">​</a></h2><p><strong>Levels and tutorials</strong></p><ul><li><strong>Play order:</strong> level 1–2 of chapter 1 (tutorials: tap, bumping), then the 28 levels of chapter 5, drawn from public-domain line art (30 levels). Set in <code>src/game/playlist.ts</code>.</li><li><strong>Tutorials:</strong> level 2 forgives the first bump (&quot;Free this time! Next bump costs a heart&quot;); level 3 (Pumpkin) teaches pinch to zoom.</li><li><strong>Pumpkin (level 3)</strong> reworked by hand: one line fewer, still solvable.</li></ul><p><strong>Boosters</strong></p><ul><li>A bottom panel (in the board colour, over the board) holds the boosters: <strong>Hint</strong> (moved from the top right) and the new <strong>Cut</strong>: arm the scissors, then tap a line or dot to remove that pair.</li></ul><p><strong>Look and feel</strong></p><ul><li><strong>New colours:</strong> dots and lines use the 28 colours of the Voxel materials, with their shading ramps for the dots&#39; rim and gloss; no white or grey. Each level is coloured with one colour scheme (complementary, split-complementary or triadic), as many of its colours as possible, near lines never in the same colour.</li><li><strong>New board colours</strong> for the light and dark themes (Settings → THEME, remembered in the browser); lines that would sink into the board get a thin edge in their own tone.</li><li><strong>Glossy dots</strong> with soft drop shadows, <strong>striped dots</strong> after a bump (their next bumps are free), dots that stretch along their path with a fading trail, and an elastic wobble on bumps instead of a screen shake.</li><li><strong>Accelerating dots:</strong> a tapped dot starts at 500 px/s and gains 250 px/s every second; bumped dots return at 1020 px/s.</li><li><strong>Cleared lines disappear</strong> with their dots; the Well Done screen shows an empty board.</li><li><strong>Ending:</strong> when the last dot is about to reach its partner the game goes into slow motion and zooms in on the meeting point; the end screen comes with the pop.</li><li><strong>Panning at any zoom</strong>, including the smallest (no more stuck off-centre board).</li></ul><p><strong>Level editor</strong></p><ul><li><strong>Chapters:</strong> each folder under <code>levels/</code> is a chapter with its own levels, history and collections.</li><li><strong>Generate from a drawing, stroke mode:</strong> each stroke of the drawing becomes one line, ends land on other strokes; smooth rounded lines with no kinks; one dot size per level (<strong>Dot size</strong>) and <strong>big dots</strong> on small round details; runs in the background so the editor never freezes. Part 2 adds an <strong>overlap pattern</strong> of X and T cross lines.</li><li><strong>Opening a local folder</strong> from the web editor works with the project folder or its <code>levels</code> folder, and errors are shown instead of silently doing nothing.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.3.0/demo/" target="_blank" rel="noreferrer">Play v0.3.0</a> · <a href="https://taigd98.github.io/dot-line/v0.3.0/docs/" target="_blank" rel="noreferrer">Docs v0.3.0</a></p><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><ul><li><strong>100 levels:</strong> played in blocks of 5 from level 2 (relax, normal, hard, normal, normal). Levels 4, 9 and 14 are a little harder than their block; from level 19 hard levels are really hard. Each level is a familiar picture (rainbow, ladder, wheel, bookshelf, spider web...), drawn as SVG in <code>art/levels/</code>.</li><li><strong>Tutorials:</strong> level 1 tap, level 2 bumping costs a heart, level 8 pinch to zoom. Hard levels show the &quot;Hard&quot; label.</li><li><strong>Big dots</strong> only as an accent or a blocker, at most one pair per level.</li><li><strong>Fix:</strong> dots that only touch at the edge no longer count as a bump (hitbox = 85% of the two radii), e.g. the top of the sailboat&#39;s left sail.</li><li><strong>Level editor:</strong> opens the game&#39;s own levels when you choose the project folder; generating with many pairs keeps the whole drawing (stuck pairs are joined instead of removed); a difficulty dial puts dots on crossing lines.</li><li><strong>Game Design Document:</strong> difficulty score (pairs, blocking depth, trap share, colours) and the level system, also in <code>design/level-system.xlsx</code>.</li><li>The 10 earlier intro levels now come after level 100.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.2.0/demo/" target="_blank" rel="noreferrer">Play v0.2.0</a> · <a href="https://taigd98.github.io/dot-line/v0.2.0/docs/" target="_blank" rel="noreferrer">Docs v0.2.0</a></p><h2 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h2><ul><li><strong>Core loop:</strong> tap a dot and it runs along its line to its partner; reaching it pops the pair (bigger dots, bigger splash) and the line stays in the Completed colour.</li><li><strong>Blocking and hearts:</strong> bumping into another pair&#39;s dot sends the dot back and costs a heart; 3 hearts, none left = level lost. Several dots can run at once.</li><li><strong>HUD:</strong> pause, hearts, hint (zooms to 1.5x and nudges a dot that can go, marked AD), progress bar, &quot;Hard&quot; label on difficulty 4+.</li><li><strong>Camera:</strong> pinch to zoom up to 3x and drag to pan; the HUD does not zoom.</li><li><strong>Win / lose screens:</strong> &quot;Well Done!&quot; with confetti and CONTINUE, &quot;Out of Hearts!&quot; with RETRY.</li><li><strong>10 intro levels:</strong> Ripples, Flag and Kite teach tapping, bumping and pinch zoom; then House, Fish, Sailboat, Umbrella, Rocket, Tree and Castle.</li><li><strong>Level editor</strong> at <code>/editor/</code>: draw and bend pairs with snapping, generate levels from a PNG or SVG drawing (always solvable, pick 1 of 3 layouts), level checks and solver, versions, collections, play test.</li><li><strong>Game Design Document:</strong> overview, core loop, rules, palette and roadmap. Level difficulty targets are still to be decided.</li></ul><p><a href="https://taigd98.github.io/dot-line/v0.1.0/demo/" target="_blank" rel="noreferrer">Play v0.1.0</a> · <a href="https://taigd98.github.io/dot-line/v0.1.0/docs/" target="_blank" rel="noreferrer">Docs v0.1.0</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-11-16</td><td>GDD created</td></tr><tr><td>2026-11-16</td><td>Imported GDD v0.2 (overview, core loop, rules, roadmap)</td></tr><tr><td>2026-11-16</td><td>Dây ở lại với màu Completed; thêm bảng màu (3.7)</td></tr><tr><td>2026-11-17</td><td>Released v0.1.0</td></tr><tr><td>2026-11-17</td><td>Released v0.2.0</td></tr><tr><td>2026-11-18</td><td>Released v0.3.0</td></tr></tbody></table>',20))])}const k=a(h,[["render",p]]);export{w as __pageData,k as default};
